function remoteControlCaptionMs(t){return Math.max(3800,Math.min(8000,Array.from(String(t||'')).length*160));}
function remoteControlOperationalNarration(text){return /^(?:我(?:先|现在|再|正在)?(?:在桌面上)?(?:看看|看一下|找一下|找找|打开|点开|翻到|翻过去|进入)|找到了(?:，|,)?我(?:现在)?(?:打开|点开)|(?:正在|开始|继续)(?:查看|打开|查找|进入)|(?:我来|让我)(?:看看|看一下|找一下|打开|点开))/.test(String(text||'').replace(/\s+/g,''));}
function remoteControlRoleTextLines(raw){if(/^\s*[\[【]?\s*(?:不说话|保持沉默|跳过发言)\s*[\]】]?\s*$/.test(String(raw||'')))return[];return splitBubbles(cleanReply(raw)).map(x=>x.replace(/^[「"']+|[」"']+$/g,'').trim()).filter(x=>x&&!/^(?:系统|提示|说明)[:：]/.test(x)&&!LEAKRE.test(x)&&!/^(?:不说话|保持沉默|跳过发言)$/.test(x)&&!remoteControlOperationalNarration(x)).slice(0,2);}
